{
    prism_percentile <- function(x, p) {
        x <- sort(x)
        n <- length(x)
        h <- (n + 1) * p
        if (h <= 1) 
            return(x[1])
        if (h >= n) 
            return(x[n])
        lo <- floor(h)
        x[lo] + (h - lo) * (x[lo + 1] - x[lo])
    }
    describe <- function(x) {
        x <- x[!is.na(x)]
        n <- length(x)
        m <- sum(x)/n
        s <- if (n > 1) 
            sqrt(sum((x - m)^2)/(n - 1))
        else NA
        ci <- if (n < 2) 
            c(NA, NA)
        else if (s == 0) 
            c(m, m)
        else t.test(x)$conf.int[1:2]
        list(n = n, min = min(x), q1 = prism_percentile(x, 0.25), median = prism_percentile(x, 
            0.5), q3 = prism_percentile(x, 0.75), max = max(x), range = max(x) - 
            min(x), mean = m, sd = s, sem = s/sqrt(n), ci_lower = ci[1], ci_upper = ci[2], 
            cv = if (m != 0) 100 * s/m else NA, geomean = if (all(x > 0)) prod(x^(1/n)) else NA, 
            sum = sum(x))
    }
    from_summary <- function(mean, sd, n) {
        if (is.na(n)) 
            return(list(n = NA, mean = mean, sd = sd, sem = NA, ci_lower = NA, ci_upper = NA, 
                cv = 100 * sd/mean))
        x <- as.numeric(scale(seq_len(n))) * sd + mean
        ci <- t.test(x)$conf.int
        list(n = n, mean = mean, sd = sd, sem = sd(x)/sqrt(n), ci_lower = ci[1], 
            ci_upper = ci[2], cv = 100 * sd/mean)
    }
}
